 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);job=DiaryJobs.get(this);if(saved!=null){editing=saved.getBoolean("editing");waiting=saved.getBoolean("waiting");id=saved.getString("id","");title=saved.getString("title","");text=saved.getString("text","");revision=saved.getLong("revision");page=saved.getInt("page");localError=saved.getString("error","");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);render();}
