 void confirmDelete(){confirmation=new Dialog(this);Dialog dialog=confirmation;dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout body=Design.col(this);Design.pad(body,22,22);body.setBackground(Design.shape(this,Design.CREAM,24));Design.text(body,"Delete this diary entry?",21,600,Design.INK);Design.space(body,14);Design.text(body,"This removes only this private journal entry. Sleep records and other entries stay unchanged.",14,400,Design.MUTED);String chosen=id;long expected=revision;Design.button(body,"Delete entry",true,()->{waiting=true;job.delete(chosen,expected);dialog.dismiss();render();});Design.button(body,"Cancel",false,dialog::dismiss);show(dialog,body);}
